});

export const mergeLabelsSchema = z
  .object({
    orgId: orgIdSchema,
    sourceLabelId: labelIdSchema,
    targetLabelId: labelIdSchema,
  })
  .refine((input) => input.sourceLabelId !== input.targetLabelId, {
    message: "Source and target labels must be different",
    path: ["targetLabelId"],
  });

export type CreateLabelInput = z.infer<typeof createLabelSchema>;
